bg=2
colors=[[9,6],[3,4]]
# Mask positions occupied by matching small objects; these positions become background.
occ={
9:{(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)},
6:{(0,0),(0,1),(1,0),(1,1),(2,1)},
3:{(0,0),(0,2),(1,1),(1,2),(2,2)},
4:{(0,0),(0,1),(0,2),(1,1),(2,1)},
}
out=[[bg]*13 for _ in range(13)]
for br in range(2):
 for bc in range(2):
  c=colors[br][bc]; top=1+br*6; left=1+bc*6
  for i in range(5):
   for j in range(5): out[top+i][left+j]=c
  for i in range(3):
   for j in range(3): out[top+1+i][left+1+j]=bg if (i,j) in occ[c] else c
print('\n'.join(' '.join(map(str,row)) for row in out))

